export const translations = {
  en: Object.fromEntries(entries.map(([bs, en]) => [bs, en])),
  de: Object.fromEntries(entries.map(([bs, , de]) => [bs, de])),
};

export function translatePhrase(value, language) {
  if (!value || language === "bs") return value;
  return translations[language]?.[value] || value;
}
